import type { Indicator, LmsRow, Sex, XAxis } from "./types";

// Re-export types that consumers need
export type { Indicator, LmsRow, Sex, XAxis };

export interface LmsSeedRow {
  indicator: Indicator;
  sex: Sex;
  xAxis: XAxis;
  xValue: number;
  l: number;
  m: number;
  s: number;
  /** The published SD band at z = {-3,-2,-1,0,+1,+2,+3}. Dev-only. */
  rawCheck: readonly [number, number, number, number, number, number, number];
}

export const LMS_VERSION = "egyptian-2021" as const;

/**
 * Convert a seed row to the canonical LmsRow format.
 */
export function toLmsRow(seed: LmsSeedRow): LmsRow {
  return {
    indicator: seed.indicator,
    sex: seed.sex,
    xAxis: seed.xAxis,
    xValue: seed.xValue,
    l: seed.l,
    m: seed.m,
    s: seed.s,
    rawCheck: seed.rawCheck,
  };
}

function r(
  indicator: Indicator,
  sex: Sex,
  xAxis: XAxis,
  xValue: number,
  l: number,
  m: number,
  s: number,
  rawCheck: readonly [number, number, number, number, number, number, number],
): LmsSeedRow {
  return { indicator, sex, xAxis, xValue, l, m, s, rawCheck };
}

